package dev.livingrealms.minecraft.entity;
import dev.livingrealms.minecraft.SimulationRuntime;import dev.livingrealms.sim.aviation.AircraftModel;import dev.livingrealms.sim.faction.RelationStatus;import java.util.Comparator;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.chat.Component;import net.minecraft.network.syncher.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.*;import net.minecraft.world.level.Level;import net.minecraft.world.phys.Vec3;
/** Physical air-combat projection of one aircraft in a canonical AirWing. */
public final class LivingRealmsAircraftEntity extends PathfinderMob{private static final EntityDataAccessor<Long> WING_ID=SynchedEntityData.defineId(LivingRealmsAircraftEntity.class,EntityDataSerializers.LONG),FACTION_ID=SynchedEntityData.defineId(LivingRealmsAircraftEntity.class,EntityDataSerializers.LONG);private static final EntityDataAccessor<Integer>SLOT=SynchedEntityData.defineId(LivingRealmsAircraftEntity.class,EntityDataSerializers.INT);private static final EntityDataAccessor<String>MODEL=SynchedEntityData.defineId(LivingRealmsAircraftEntity.class,EntityDataSerializers.STRING);private boolean dematerializing,lossReported;
public LivingRealmsAircraftEntity(EntityType<? extends LivingRealmsAircraftEntity> type,Level level){super(type,level);setPersistenceRequired();setNoGravity(true);}public static AttributeSupplier.Builder createAttributes(){return PathfinderMob.createMobAttributes().add(Attributes.MAX_HEALTH,35).add(Attributes.FOLLOW_RANGE,96).add(Attributes.ATTACK_DAMAGE,8).add(Attributes.ARMOR,3).add(Attributes.MOVEMENT_SPEED,.35);}@Override protected void registerGoals(){}@Override protected void defineSynchedData(SynchedEntityData.Builder b){super.defineSynchedData(b);b.define(WING_ID,0L);b.define(FACTION_ID,0L);b.define(SLOT,-1);b.define(MODEL,AircraftModel.LIGHT_FIGHTER.name());}
public void initializeProjection(long wing,long faction,int slot,AircraftModel model){if(wing<=0||faction<=0||slot<0||model==null)throw new IllegalArgumentException("air projection");entityData.set(WING_ID,wing);entityData.set(FACTION_ID,faction);entityData.set(SLOT,slot);entityData.set(MODEL,model.name());applyModel();}public long wingId(){return entityData.get(WING_ID);}public long factionId(){return entityData.get(FACTION_ID);}public int projectionSlot(){return entityData.get(SLOT);}public AircraftModel aircraftModel(){try{return AircraftModel.valueOf(entityData.get(MODEL));}catch(IllegalArgumentException e){return AircraftModel.LIGHT_FIGHTER;}}public boolean isDematerializing(){return dematerializing;}public boolean lossReported(){return lossReported;}public void markLossReported(){lossReported=true;}public void dematerialize(){dematerializing=true;discard();}
@Override public void tick(){super.tick();setNoGravity(true);fallDistance=0;if(level().isClientSide()||!(level() instanceof ServerLevel sl))return;var state=SimulationRuntime.data(sl.getServer()).state();var wing=state.airWings().stream().filter(w->w.id()==wingId()).findFirst().orElse(null);if(wing==null||wing.destroyed()){dematerialize();return;}Vec3 destination=new Vec3(wing.position().x(),Math.max(sl.getSeaLevel()+45,getY()),wing.position().z());Vec3 delta=destination.subtract(position());if(delta.lengthSqr()>16){double speed=.42+aircraftModel().speed()/5000.0;setDeltaMovement(delta.normalize().scale(speed));setYRot((float)(Math.atan2(-delta.x,delta.z)*180/Math.PI));}else setDeltaMovement(getDeltaMovement().scale(.88));if(tickCount%20==0){LivingRealmsAircraftEntity enemy=AircraftProjectionIndex.loaded().stream().filter(e->e!=this&&e.isAlive()&&hostile(state,e.factionId())&&distanceToSqr(e)<85*85).min(Comparator.comparingDouble(this::distanceToSqr)).orElse(null);if(enemy!=null&&distanceToSqr(enemy)<45*45)enemy.hurt(damageSources().mobAttack(this),(float)(3+aircraftModel().attack()*3));}}
private boolean hostile(dev.livingrealms.sim.world.SimulationState state,long other){return state.findFaction(factionId()).map(f->{var r=f.relations().get(other);return r!=null&&r.status()==RelationStatus.WAR;}).orElse(false);}private void applyModel(){double hp=25+aircraftModel().attack()*12+aircraftModel().cargo();setBase(Attributes.MAX_HEALTH,hp);setBase(Attributes.ARMOR,2+aircraftModel().attack()*2);setHealth(getMaxHealth());setCustomName(Component.literal(aircraftModel().name().toLowerCase().replace('_',' ')));setCustomNameVisible(false);}private void setBase(net.minecraft.core.Holder<Attribute>a,double v){AttributeInstance i=getAttribute(a);if(i!=null)i.setBaseValue(v);}
@Override public void addAdditionalSaveData(CompoundTag t){super.addAdditionalSaveData(t);t.putLong("LRWing",wingId());t.putLong("LRFaction",factionId());t.putInt("LRSlot",projectionSlot());t.putString("LRModel",aircraftModel().name());t.putBoolean("LRDematerializing",dematerializing);t.putBoolean("LRLossReported",lossReported);}@Override public void readAdditionalSaveData(CompoundTag t){super.readAdditionalSaveData(t);entityData.set(WING_ID,t.getLong("LRWing"));entityData.set(FACTION_ID,t.getLong("LRFaction"));entityData.set(SLOT,t.getInt("LRSlot"));entityData.set(MODEL,t.getString("LRModel"));dematerializing=t.getBoolean("LRDematerializing");lossReported=t.getBoolean("LRLossReported");setNoGravity(true);applyModel();}}
